$root = 'C:\Users\eric_rash\Desktop\DEV'
$skip = @('.claude','_tools','_DRIVE','token-dashboard')
$dirs = @()
$dirs += Get-ChildItem $root -Directory -Force
foreach ($sub in 'Football','SpecialRequests') { if (Test-Path "$root\$sub") { $dirs += Get-ChildItem "$root\$sub" -Directory -Force } }
$dirs = $dirs | Where-Object { $skip -notcontains $_.Name -and $_.Name -notlike '*_OLD_merged*' -and $_.Name -notlike '.*' }
$rows = foreach ($d in $dirs) {
  $p = $d.FullName
  if (-not (Test-Path "$p\.git")) {
    # Football/SpecialRequests parents may be non-repo groupers
    [pscustomobject]@{Name=$p.Substring($root.Length+1); State='NOREPO'; Dirty=0; Ahead=0; Behind=0; Remote=''}
    continue
  }
  $remote = git -C $p remote get-url origin 2>$null
  $dirty = (git -C $p status --porcelain 2>$null | Measure-Object).Count
  $ahead = 0; $behind = 0
  if ($remote) {
    git -C $p fetch -q origin 2>$null
    $ab = git -C $p rev-list --left-right --count '@{u}...HEAD' 2>$null
    if ($ab) { $parts = $ab -split '\s+'; $behind = [int]$parts[0]; $ahead = [int]$parts[1] } else { $ahead = -1 }
  }
  [pscustomobject]@{Name=$p.Substring($root.Length+1); State=($(if ($remote) {'OK'} else {'NOREMOTE'})); Dirty=$dirty; Ahead=$ahead; Behind=$behind; Remote=$remote}
}
$rows | Export-Csv "$PSScriptRoot\inv.csv" -NoTypeInformation
Write-Output ("total {0}" -f $rows.Count)
$rows | Where-Object { $_.State -ne 'OK' -or $_.Dirty -gt 0 -or $_.Ahead -ne 0 -or $_.Behind -gt 0 } | Format-Table Name,State,Dirty,Ahead,Behind -AutoSize | Out-String -Width 200
$remotes = $rows | Where-Object Remote | ForEach-Object { ($_.Remote -replace '\.git$','') -replace '.*/','' }
$gh = (gh repo list erash11 --limit 300 --json name | ConvertFrom-Json).name
$ghskip = @('dotclaude','SecondBrain','claude-skills','claude-memory-compiler','DEV','DexaProject','claude-global-memory')
Write-Output "missing locally:"
$gh | Where-Object { $remotes -notcontains $_ -and $ghskip -notcontains $_ }

